insert into shop_products (id, shop_id, category_id, name, description, price, photo, available, position)
select md5('SHISO:' || (x->>0))::uuid, (select id from shops where code='SHISO'), md5('SHISO:cat:' || (x->>1))::uuid, x->>3, nullif(x->>4, ''), (x->>5)::numeric,
